const SERVER = `${window.location.protocol}//${window.location.hostname}:5006`;
const enabled = document.getElementById("agent-mode-toggle");
const state = document.getElementById("agent-mode-state");
const output = document.getElementById("workflow-results");
const storageKey = "multi_agent_mode_enabled";
function renderState(){state.textContent=enabled.checked?"ON":"OFF";state.classList.toggle("feature-on",enabled.checked);state.classList.toggle("feature-off",!enabled.checked);}
function renderPayload(title,payload){const heading=document.createElement("h3");heading.textContent=title;const pre=document.createElement("pre");pre.textContent=JSON.stringify(payload,null,2);output.replaceChildren(heading,pre);}
async function postJson(path,payload){
  let response;
  try {
    response = await fetch(`${SERVER}${path}`, {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)});
  } catch (error) {
    throw new Error(`Cannot reach Multi-Agent API at ${SERVER}. Check that the multi-agent-server container is running and port 5006 is published. Browser detail: ${error.message}`);
  }
  const raw = await response.text();
  let data;
  try { data = raw ? JSON.parse(raw) : {}; } catch (_) { data = {error: raw || "The API returned an empty response."}; }
  if(!response.ok) throw new Error(data.error||data.message||`Request failed (${response.status})`);
  return data;
}
enabled.checked=localStorage.getItem(storageKey)!=="false";renderState();enabled.addEventListener("change",()=>{localStorage.setItem(storageKey,String(enabled.checked));renderState();if(!enabled.checked)output.textContent="Multi-Agent Mode is OFF. Enable it to run workflows.";});
