const BACKEND = "http://localhost:5001";

async function renderIntoPanel(panelId, url, options = {}) {
  const panel = document.getElementById(panelId);
  try {
    const response = await fetch(url, options);
    const body = await response.text();
    panel.innerHTML = body;
    return response;
  } catch (error) {
    panel.innerHTML = `
Request failed.${error}`;
  }
}

async function populateSelect(selectEl, url, placeholder) {
  try {
    const response = await fetch(url);
    const html = await response.text();
    selectEl.innerHTML = (placeholder ? `${placeholder}` : "") + html;
  } catch (error) {
    selectEl.innerHTML = `Failed to load`;
  }
}

function initDropdowns() {
  populateSelect(document.getElementById("category-filter"), `${BACKEND}/categories/options`, "All categories");
  populateSelect(document.getElementById("supplier-filter"), `${BACKEND}/suppliers/options`, "All suppliers");
  populateSelect(document.getElementById("add_category_id"), `${BACKEND}/categories/options`, "");
  populateSelect(document.getElementById("add_supplier_id"), `${BACKEND}/suppliers/options`, "");
  populateSelect(document.getElementById("upd_category_id"), `${BACKEND}/categories/options`, "");
  populateSelect(document.getElementById("upd_supplier_id"), `${BACKEND}/suppliers/options`, "");
}
initDropdowns();

function loadProducts() {
  const params = new URLSearchParams();
  const search = document.getElementById("search-input").value.trim();
  const category = document.getElementById("category-filter").value;
  const supplier = document.getElementById("supplier-filter").value;
  const sortBy = document.getElementById("sort-by").value;
  const sortDir = document.getElementById("sort-dir").value;
  if (search) params.set("search", search);
  if (category) params.set("category_id", category);
  if (supplier) params.set("supplier_id", supplier);
  params.set("sort_by", sortBy);
  params.set("sort_dir", sortDir);
  renderIntoPanel("products-result", `${BACKEND}/products?${params.toString()}`);
}
loadProducts();

document.getElementById("apply-filters-btn").addEventListener("click", loadProducts);
document.getElementById("low-stock-btn").addEventListener("click", () => {
  renderIntoPanel("products-result", `${BACKEND}/products/low-stock`);
});

// Add product
document.getElementById("add-product-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const formData = new URLSearchParams(new FormData(event.target));
  await renderIntoPanel("add-product-result", `${BACKEND}/products`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: formData,
  });
  event.target.reset();
  loadProducts();
});

// Find product to edit
let currentEditId = null;
document.getElementById("find-product-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const id = document.getElementById("edit_product_id").value;
  const response = await fetch(`${BACKEND}/products/${id}`);
  const body = await response.text();
  document.getElementById("product-lookup-result").innerHTML = body;
  const updateForm = document.getElementById("update-product-form");
  if (response.ok) {
    currentEditId = id;
    updateForm.classList.remove("is-hidden");
  } else {
    currentEditId = null;
    updateForm.classList.add("is-hidden");
  }
});

// Update product
document.getElementById("update-product-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!currentEditId) return;
  const formData = new URLSearchParams(new FormData(event.target));
  await renderIntoPanel("update-product-result", `${BACKEND}/products/${currentEditId}`, {
    method: "PUT",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: formData,
  });
  loadProducts();
});

// Delete product
document.getElementById("delete-product-btn").addEventListener("click", async () => {
  if (!currentEditId) return;
  if (!confirm(`Delete product ${currentEditId}? This cannot be undone.`)) return;
  await renderIntoPanel("update-product-result", `${BACKEND}/products/${currentEditId}`, {
    method: "DELETE",
  });
  document.getElementById("update-product-form").classList.add("is-hidden");
  currentEditId = null;
  loadProducts();
});

// Stocktake
document.getElementById("stocktake-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  const formData = new URLSearchParams(new FormData(event.target));
  await renderIntoPanel("stocktake-add-result", `${BACKEND}/stocktakes`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: formData,
  });
  event.target.reset();
  loadProducts();
});

document.getElementById("load-stocktakes-btn").addEventListener("click", () => {
  renderIntoPanel("stocktake-history-result", `${BACKEND}/stocktakes`);
});











