import os

import requests

RAG_SERVICE_URL = os.getenv("RAG_SERVICE_URL", "http://host.docker.internal:5003")
RAG_ENABLED = os.getenv("RAG_ENABLED", "true").strip().lower() in ("1", "true", "yes", "on")

try:
    RAG_SERVICE_TIMEOUT_SECONDS = int(os.getenv("RAG_SERVICE_TIMEOUT_SECONDS", "180"))
except ValueError:
    RAG_SERVICE_TIMEOUT_SECONDS = 180


def rag_mode_is_enabled(req) -> bool:
    if not RAG_ENABLED:
        return False
    mode_header = req.headers.get("X-RAG-Mode", "on").strip().lower()
    return mode_header in ("1", "true", "yes", "on")


def rag_disabled_response():
    return {"status": "error", "error": "RAG mode is disabled."}, 403


def call_rag_service(path: str, payload: dict):
    response = requests.post(f"{RAG_SERVICE_URL}{path}", json=payload, timeout=RAG_SERVICE_TIMEOUT_SECONDS)
    try:
        data = response.json()
    except ValueError:
        response.raise_for_status()
        return {}
    if response.status_code >= 400:
        raise requests.HTTPError(f"RAG service {path} failed with status {response.status_code}: {data}", response=response)
    return data







def format_products_html(products):
    if not products:
        return "
No products found."
    rows = ""
    for p in products:
        low_stock = p["quantity"] <= p["reorder_level"]
        badge = (
            'Low stock'
            if low_stock
            else 'OK'
        )
        rows += (
            "
"
            f"{p['product_id']}"
            f"{p['name']}"
            f"{p.get('brand') or '-'}"
            f"{p['category_name']}"
            f"{p['supplier_name']}"
            f"${p['price']:.2f}"
            f"{p['quantity']}"
            f"{badge}"
            ""
        )
    return (
        ''
        "
IDNameBrandCategory"
        "SupplierPriceQtyStatus"
        f"{rows}"
    )


def format_product_html(product):
    return (
        "
"
        f"
ID: {product['product_id']}"
        f"
Name: {product['name']}"
        f"
Brand: {product.get('brand') or '-'}"
        f"
Description: {product.get('description') or '-'}"
        f"
Category: {product['category_name']}"
        f"
Supplier: {product['supplier_name']}"
        f"
Price: ${product['price']:.2f}"
        f"
Quantity: {product['quantity']}"
        f"
Reorder level: {product['reorder_level']}"
        ""
    )


def format_categories_options(categories):
    return "".join(f"{c['name']}" for c in categories)


def format_suppliers_options(suppliers):
    return "".join(f"{s['name']}" for s in suppliers)


def format_stocktakes_html(stocktakes):
    if not stocktakes:
        return "
No stocktake activity recorded yet."
    rows = ""
    for s in stocktakes:
        rows += (
            "
"
            f"{s['stocktake_id']}"
            f"{s['product_name']}"
            f"{s['member_name']}"
            f"{s['counted_quantity']}"
            f"{s['timestamp']}"
            ""
        )
    return (
        ''
        "
IDProductMemberCounted QtyTimestamp"
        f"{rows}"
    )



from pathlib import Path
import sys

from flask import Flask
from flask_cors import CORS

BASE_DIR = Path(__file__).resolve().parent
if str(BASE_DIR) not in sys.path:
    sys.path.insert(0, str(BASE_DIR))

from routes.ai_mode import ai_mode_bp
from routes.normal_ui import normal_ui_bp
from routes.mcp_mode import mcp_bp
from routes.rag_mode import rag_bp
from routes.multi_agent_mode import multi_agent_bp


def create_app():
    app = Flask(__name__)
    CORS(app)
    app.register_blueprint(normal_ui_bp)
    app.register_blueprint(ai_mode_bp)
    app.register_blueprint(mcp_bp)
    app.register_blueprint(rag_bp)
    app.register_blueprint(multi_agent_bp)
    return app


app = create_app()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5001, debug=True)



